,\n        \"trailing\": \"\"\n      }\n    },\n    {\n      \"request\": \"job:limits-requested\",\n      \"result\": \"job:limits-result\",\n      \"failure\": \"job:limits-failed\",\n      \"docs\": {\n        \"lead\": [],\n        \"trailing\": \"\"\n      }\n    },\n    {\n      \"request\": \"job:cancel-requested\",\n      \"result\": \"job:cancel-ok\",\n      \"failure\": \"job:cancel-failed\",\n      \"docs\": {\n        \"lead\": [],\n        \"trailing\": \"\"\n      }\n    },\n    {\n      \"request\": \"job:claim\",\n      \"result\": \"job:claimed\",\n      \"failure\": \"job:claim-failed\",\n      \"docs\": {\n        \"lead\": [\n          {\n            \"comment\": [\n              \"worker-side: the worker claims a queued job (not an SDK call)\"\n            ]\n          }\n        ],\n        \"trailing\": \"\"\n      }\n    },\n    {\n      \"request\": \"mark:create-request\",\n      \"result\": \"mark:create-ok\",\n      \"failure\": \"mark:create-failed\",\n      \"docs\": {\n        \"lead\": [\n          \"\",\n          {\n            \"section\": \"MARK\"\n          }\n        ],\n        \"trailing\": \"\"\n      }\n    },\n    {\n      \"request\": \"mark:commit\",\n      \"result\": \"mark:commit-ok\",\n      \"failure\": \"mark:commit-failed\",\n      \"docs\": {\n        \"lead\": [],\n        \"trailing\": \"\"\n      }\n    },\n    {\n      \"request\": \"mark:delete\",\n      \"result\": \"mark:delete-ok\",\n      \"failure\": \"mark:delete-failed\",\n      \"docs\": {\n        \"lead\": [],\n        \"trailing\": \"\"\n      }\n    },\n    {\n      \"request\": \"mark:archive\",\n      \"result\": \"mark:archive-ok\",\n      \"failure\": \"mark:archive-failed\",\n      \"docs\": {\n        \"lead\": [],\n        \"trailing\": \"\"\n      }\n    },\n    {\n      \"request\": \"mark:unarchive\",\n      \"result\": \"mark:unarchive-ok\",\n      \"failure\": \"mark:unarchive-failed\",\n      \"docs\": {\n        \"lead\": [],\n        \"trailing\": \"\"\n      }\n    },\n    {\n      \"request\": \"mark:update-entity-types\",\n      \"result\": \"mark:update-entity-types-ok\",\n      \"failure\": \"mark:update-entity-types-failed\",\n      \"docs\": {\n        \"lead\": [],\n        \"trailing\": \"\"\n      }\n    },\n    {\n      \"request\": \"match:search-requested\",\n      \"result\": \"match:search-results\",\n      \"failure\": \"match:search-failed\",\n      \"docs\": {\n        \"lead\": [\n          \"\",\n          {\n            \"section\": \"MATCH\"\n          },\n          {\n            \"comment\": [\n              \"take-1 dressed as an Observable in the SDK\"\n            ]\n          }\n        ],\n        \"trailing\": \"\"\n      }\n    },\n    {\n      \"request\": \"match:resources-requested\",\n      \"result\": \"match:resources-result\",\n      \"failure\": \"match:resources-failed\",\n      \"docs\": {\n        \"lead\": [],\n        \"trailing\": \"\"\n      }\n    },\n    {\n      \"request\": \"match:limits-requested\",\n      \"result\": \"match:limits-result\",\n      \"failure\": \"match:limits-failed\",\n      \"docs\": {\n        \"lead\": [],\n        \"trailing\": \"\"\n      }\n    },\n    {\n      \"request\": \"weave:rebuild\",\n      \"result\": \"weave:rebuild-ok\",\n      \"failure\": \"weave:rebuild-failed\",\n      \"docs\": {\n        \"lead\": [\n          \"\",\n          {\n            \"section\": \"WEAVE\"\n          },\n          {\n            \"comment\": [\n              \"Graph-projection rebuild, served by the Weaver\"\n            ]\n          }\n        ],\n        \"trailing\": \"\"\n      }\n    },\n    {\n      \"request\": \"smelt:rebuild-anchors\",\n      \"result\": \"smelt:rebuild-anchors-ok\",\n      \"failure\": \"smelt:rebuild-anchors-failed\",\n      \"docs\": {\n        \"lead\": [\n          \"\",\n          {\n            \"section\": \"SMELT\"\n          },\n          {\n            \"comment\": [\n              \"Anchored-text rebuild, served by the Smelter\"\n            ]\n          }\n        ],\n        \"trailing\": \"\"\n      }\n    },\n    {\n      \"request\": \"yield:create\",\n      \"result\": \"yield:create-ok\",\n      \"failure\": \"yield:create-failed\",\n      \"docs\": {\n        \"lead\": [\n          \"\",\n          {\n            \"section\": \"YIELD\"\n          },\n          {\n            \"comment\": [\n              \"clients refresh on the persisted `yield:created`, never on the -ok reply\"\n            ]\n          }\n        ],\n        \"trailing\": \"\"\n      }\n    },\n    {\n      \"request\": \"yield:clone-persist\",\n      \"result\": \"yield:clone-persist-ok\",\n      \"failure\": \"yield:clone-persist-failed\",\n      \"docs\": {\n        \"lead\": [],\n        \"trailing\": \"\"\n      }\n    },\n    {\n      \"request\": \"yield:update\",\n      \"result\": \"yield:update-ok\",\n      \"failure\": \"yield:update-failed\",\n      \"docs\": {\n        \"lead\": [\n          {\n            \"comment\": [\n              \"dormant \u2014 handler in stower exists, no request emitter\"\n            ]\n          }\n        ],\n        \"trailing\": \"\"\n      }\n    },\n    {\n      \"request\": \"yield:clone-create\",\n      \"result\": \"yield:clone-created\",\n      \"failure\": \"yield:clone-create-failed\",\n      \"docs\": {\n        \"lead\": [],\n        \"trailing\": \"\"\n      }\n    },\n    {\n      \"request\": \"yield:clone-resource-requested\",\n      \"result\": \"yield:clone-resource-result\",\n      \"failure\": \"yield:clone-resource-failed\",\n      \"docs\": {\n        \"lead\": [],\n        \"trailing\": \"\"\n      }\n    },\n    {\n      \"request\": \"yield:clone-token-requested\",\n      \"result\": \"yield:clone-token-generated\",\n      \"failure\": \"yield:clone-token-failed\",\n      \"docs\": {\n        \"lead\": [],\n        \"trailing\": \"\"\n      }\n    }\n  ],\n  \"docs\": {\n    \"eventName\": [\n      \"Any valid channel name on the EventBus \u2014 `keyof EventMap`, the root channel type. Two subsets matter, and confusing them is a silent-failure trap:\",\n      {\n        \"items\": [\n          \"`EmittableChannel` (below) \u2014 channels with a non-null `CHANNEL_SCHEMAS` entry; what you EMIT (the `/bus/emit` gateway validates the payload).\",\n          \"`BridgedChannel` (`bridged-channels.ts`) \u2014 the transport fan-in set; the only channels a client can SUBSCRIBE to over a concrete transport.\"\n        ]\n      },\n      \"Request/reply (`Bus.request`) emits on an `EmittableChannel` and subscribes on `BridgedChannel` replies. A reply channel that is a valid `EventName` but NOT in `BRIDGED_CHANNELS` is never delivered \u2192 the request times out with no compile or runtime error. `Bus.request` therefore takes no reply channels: it looks them up in `BUS_OPERATIONS`, from which `BRIDGED_CHANNELS` derives.\"\n    ],\n    \"enrichedEvents\": [\n      \"Channels whose published event carries the annotation as it stands in the view \u2014 the registry's `enriched` flag, generated so the flag and the code that acts on it cannot disagree.\",\n      \"The enricher switches on THIS list: a flag with no case fails to compile rather than silently never attaching, which consumers cannot detect because `annotation` is optional and their absent-branch is indistinguishable from a genuine decline.\",\n      \"Typed `PersistedEventType`, not `EventName`: the validator already allows the flag only on a stored event, so this makes enriched \u2286 persisted a compile-time fact rather than a convention.\"\n    ],\n    \"channelSchemas\": [\n      \"Authoritative map from bus channel to OpenAPI schema name.\",\n      \"Every `EventName` must appear. The `satisfies` clause below enforces completeness at compile time \u2014 adding a channel to `EventMap` without adding an entry here is a build error.\",\n      \"Values:\",\n      {\n        \"items\": [\n          \"`<SchemaName>`: payload validates against `components['schemas'][SchemaName]`.\",\n          \"`null`: no single-schema validation. Used for branded `StoredEvent` wrappers, `void` UI signals, and inline wrapper types (e.g. `{ response: T }`). These are not validated by `/bus/emit`.\"\n        ]\n      },\n      \"The gateway's `/bus/emit` route validates against the same registry entries. Consumers can use this map for client-side pre-flight validation before emitting.\"\n    ],\n    \"emittableChannel\": [\n      \"Channels where `/bus/emit` validates the payload (non-null schema).\"\n    ]\n  },\n  \"inProcess\": {\n    \"doc\": [\n      \"Explicitly LOCAL-ONLY: these channels never cross the signal plane \u2014 UI signals, event-log appends, and single-process relays. Membership is a DECISION, not a default: a channel absent from every class (operations, outboundCommands, bridgedBroadcasts, here) refuses to generate. There is no fallthrough: one would silently classify a wire channel such as `job:queued` as in-process and starve every worker.\"\n    ],\n    \"channels\": [\n      \"yield:clone\",\n      \"mark:requested\",\n      \"mark:submit\",\n      \"mark:delegate-timeout\",\n      \"mark:create-error\",\n      \"mark:delete-error\",\n      \"bind:body-error\",\n      \"bind:initiate\",\n      \"browse:entity-type-clicked\",\n      \"panel:toggle\",\n      \"panel:open\",\n      \"panel:close\",\n      \"shell:sidebar-toggle\",\n      \"tabs:close\",\n      \"tabs:reorder\",\n      \"nav:link-clicked\",\n      \"nav:push\",\n      \"nav:external\",\n      \"beckon:hover\",\n      \"settings:theme-changed\",\n      \"settings:line-numbers-toggled\",\n      \"settings:locale-changed\",\n      \"settings:hover-delay-changed\"\n    ]\n  },\n  \"kind\": {\n    \"doc\": [\n      \"How a wire-crossing channel behaves. An OPERATION's channels are absent: their kind follows from `operations`, and restating a derivable fact is a mirror with nothing to gate it.\",\n      \"`kind`, not `shape` \u2014 `channels[]` entries already use `shape` for the PAYLOAD shape, and two facts under one key in one file is the disease this taxonomy exists to cure.\",\n      {\n        \"items\": [\n          \"command \u2014 no reply pair; a directive for whichever single handler owns it\",\n          \"event \u2014 a fact announced after it happened; consumers react, nobody replies\"\n        ]\n      }\n    ],\n    \"command\": [\n      \"job:checkpoint\",\n      \"job:cancel\",\n      \"job:start\",\n      \"job:assign\",\n      \"mark:update-body\",\n      \"principal:profile\"\n    ],\n    \"event\": [\n      \"job:report-progress\",\n      \"job:complete\",\n      \"job:fail\",\n      \"job:queued\",\n      \"smelt:settled\",\n      \"frame:entity-type-added\",\n      \"frame:tag-schema-added\",\n      \"yield:created\",\n      \"yield:updated\",\n      \"yield:cloned\",\n      \"yield:moved\",\n      \"beckon:focus\",\n      \"beckon:sparkle\",\n      \"bus:resume-gap\",\n      \"browse:resource-open\",\n      \"browse:resource-viewed\",\n      \"session:joined\",\n      \"session:left\",\n      \"browse:click\",\n      \"mark:body-updated\",\n      \"weave:applied\",\n      \"yield:representation-added\",\n      \"yield:representation-removed\",\n      \"mark:added\",\n      \"mark:removed\",\n      \"mark:entity-tag-added\",\n      \"mark:entity-tag-removed\",\n      \"mark:archived\",\n      \"mark:unarchived\",\n      \"job:started\",\n      \"job:assigned\",\n      \"job:completed\",\n      \"job:failed\",\n      \"mark:body-update-failed\",\n      \"principal:profiled\"\n    ]\n  },\n  \"audience\": {\n    \"doc\": [\n      \"WHO receives a wire-crossing channel \u2014 independent of `kind` and of `recorded`. An OPERATION's channels are absent: a request reaches the one service that answers it, and a reply is correlated-addressed to its owner.\",\n      {\n        \"items\": [\n          \"everyone \u2014 every full client subscribes, with every operation's reply channels (derives BRIDGED_CHANNELS)\",\n          \"scoped \u2014 delivered to clients that joined the frame's RESOURCE scope (derives RESOURCE_SCOPED_CHANNELS)\",\n          \"declared \u2014 only clients whose manifest names it: workers, sidecars, and the gateway's own handlers\"\n        ]\n      }\n    ],\n    \"everyone\": [\n      \"job:report-progress\",\n      \"job:complete\",\n      \"job:fail\",\n      \"smelt:settled\",\n      \"frame:entity-type-added\",\n      \"frame:tag-schema-added\",\n      \"yield:created\",\n      \"yield:updated\",\n      \"yield:cloned\",\n      \"yield:moved\",\n      \"beckon:focus\",\n      \"beckon:sparkle\",\n      \"bus:resume-gap\",\n      \"browse:resource-open\",\n      \"browse:resource-viewed\",\n      \"session:joined\",\n      \"session:left\",\n      \"browse:click\"\n    ],\n    \"scoped\": [\n      \"mark:body-updated\",\n      \"yield:representation-added\",\n      \"yield:representation-removed\",\n      \"mark:added\",\n      \"mark:removed\",\n      \"mark:entity-tag-added\",\n      \"mark:entity-tag-removed\",\n      \"mark:archived\",\n      \"mark:unarchived\",\n      \"job:started\",\n      \"job:assigned\",\n      \"job:completed\",\n      \"job:failed\"\n    ],\n    \"declared\": [\n      \"job:queued\",\n      \"job:checkpoint\",\n      \"job:cancel\",\n      \"job:start\",\n      \"job:assign\",\n      \"mark:update-body\",\n      \"weave:applied\",\n      \"mark:body-update-failed\",\n      \"principal:profiled\",\n      \"principal:profile\"\n    ]\n  },\n  \"effect\": {\n    \"doc\": [\n      \"Does emitting this channel CHANGE the knowledge base, or only ask it something?\",\n      \"A WRITE is an act: it appends to the event log, or it enqueues or transitions durable work the log will later cite. A READ answers from state that already exists and leaves nothing behind \u2014 every `browse:*` request, and the three lookups that merely resolve a token or a summary.\",\n      \"The domain is exactly the EMITTABLE set: an operation's request, or a `kind: command`. Inbound replies, broadcast events and in-process UI signals are absent because nobody emits them at the gateway, so the question does not arise. Every emittable channel names one side or the other and the generator refuses \u2014 there is no default.\",\n      \"The gateway reads this to decide when the record learns a principal's name: a `_userId` stamp is NOT the test, because a read carries one too. Someone who signs in and only browses is never named, and the profile publish rate is the WRITE rate rather than the emit rate \u2014 orders of magnitude apart.\"\n    ],\n    \"writes\": [\n      \"bind:update-body\",\n      \"frame:add-entity-type\",\n      \"frame:add-tag-schema\",\n      \"job:assign\",\n      \"job:cancel\",\n      \"job:cancel-requested\",\n      \"job:checkpoint\",\n      \"job:claim\",\n      \"job:create\",\n      \"job:start\",\n      \"mark:archive\",\n      \"mark:commit\",\n      \"mark:create-request\",\n      \"mark:delete\",\n      \"mark:unarchive\",\n      \"mark:update-body\",\n      \"mark:update-entity-types\",\n      \"principal:profile\",\n      \"smelt:rebuild-anchors\",\n      \"weave:rebuild\",\n      \"yield:clone-create\",\n      \"yield:clone-persist\",\n      \"yield:create\",\n      \"yield:update\"\n    ],\n    \"reads\": [\n      \"browse:engines-requested\",\n      \"browse:annotation-history-requested\",\n      \"browse:annotation-requested\",\n      \"browse:directory-requested\",\n      \"browse:entity-types-requested\",\n      \"browse:events-requested\",\n      \"browse:kb-requested\",\n      \"browse:profiles-requested\",\n      \"browse:resource-requested\",\n      \"browse:resources-requested\",\n      \"browse:tag-schemas-requested\",\n      \"gather:limits-requested\",\n      \"gather:referenced-by-requested\",\n      \"gather:requested\",\n      \"gather:resource-requested\",\n      \"gather:summary-requested\",\n      \"job:limits-requested\",\n      \"job:status-requested\",\n      \"match:limits-requested\",\n      \"match:resources-requested\",\n      \"match:search-requested\",\n      \"yield:clone-resource-requested\",\n      \"yield:clone-token-requested\"\n    ]\n  },\n  \"trace\": {\n    \"meaning\": \"The field of a relayed frame's payload that carries the trace the frame was published under: an object of W3C's `traceparent` and, when it has one, `tracestate`. A frame the gateway relays over the stream has no headers of its own, so the gateway writes the field on its payload, and a receiver takes it off before the payload is delivered and continues the trace from it. No payload schema declares it, and no subscriber sees it. An emit carries its trace in its request's `traceparent` header, and its payload carries no such field.\",\n    \"field\": \"_trace\"\n  }\n}\n";
    internal const string Timing = "{\n  \"$comment\": \"AUTHORITY for the timing a Xynolog client keeps: its deadlines, its retry budgets and the cadence of its stream. Every SDK generates its constants from this file, so one client waits as long, and tries as often, as another. A name ending in `Ms` is a duration in milliseconds; one ending in `Retry` is a budget of `attempts` with a backoff that starts at `initialDelayMs` and doubles to `maxDelayMs`; one ending in `Count` is a whole number of things. TypeScript: the consumer-owned generator writes sdk/typescript/core/src/client-timing.ts. An SDK's testing surface may override any of these; these are what it does unasked. Which failures are worth an attempt is specs/src/retry/cases.json.\",\n  \"timing\": [\n    {\n      \"name\": \"busRequestTimeoutMs\",\n      \"value\": 30000,\n      \"docs\": \"How long a bus request has, from the call, to be answered: the wait for the stream to open, the emit with its retries and the waits between them, and the wait for the reply. When it falls due the request fails as timed out, and an emit still in flight is given up, with no attempt after it. The gateway keeps a reply for redelivery at least twice this long (`replyRetentionSeconds` on POST /bus/subscribe), so a reply published during an outage is still there when the requester reconnects inside its own deadline.\"\n    },\n    {\n      \"name\": \"emitTimeoutMs\",\n      \"value\": 30000,\n      \"docs\": \"The deadline on one POST /bus/emit. The gateway accepts an emit promptly; one still unanswered here means the gateway is unresponsive, and the emit is rejected rather than awaited forever. Without it a worker's emit to a wedged gateway hangs its loop.\"\n    },\n    {\n      \"name\": \"emitRetry\",\n      \"value\": {\n        \"attempts\": 4,\n        \"initialDelayMs\": 1000,\n        \"maxDelayMs\": 4000\n      },\n      \"docs\": \"The retry budget of ONE emit. Per request, never per boot pass: re-running a whole catch-up pass to recover from one refusal re-sends hundreds of emits that already succeeded. Small on purpose: an emit a caller awaits must fail while the caller still cares, and the patience for a gateway that is down belongs to the pass above it.\"\n    },\n    {\n      \"name\": \"httpRequestTimeoutMs\",\n      \"value\": 30000,\n      \"docs\": \"The deadline on one HTTP request that is neither the stream nor an emit: one of the gateway's own operations (who a token is, a media token, the resource metadata, health, status), the wait for a resource's bytes to begin arriving, a read of a resource's description or of its anchored text, a request to the issuer (its discovery, a grant, a revocation), and a read of a launcher's discovery document. Unanswered here, the request fails as one that got no answer. It bounds the read of a refusal's body too, of such a request or of the request that opens the stream (`streamOpenTimeoutMs`): a body not read by then is the refusal with none of the gateway's words, refused, renewed or retried as any refusal is. Without it, a gateway or an issuer that accepts a connection and never answers holds a session's start, and every renewal after it, for as long as the process lives. An upload has no deadline: how long it takes is how large the resource is. A read of anchored text may be held by the Archivist while the Smelter reads the content, and the gateway waits for the Archivist as the Archivist's document states (specs/src/archivist/openapi.json): this deadline is longer than its `connectSeconds` and `readSeconds` together, and the hold is shorter than `readSeconds`, which `lint:spec-protocol` holds.\"\n    },\n    {\n      \"name\": \"requestRetryPauseMs\",\n      \"value\": 300,\n      \"docs\": \"The wait before an HTTP request that is neither the stream nor an emit is made a second time. It is made again when the gateway answered it with a status that promises recovery, or did not answer at all, and a repeat cannot cause a second effect: its method cannot, or it carries an `Idempotency-Key`, as an upload does (`transport` in specs/src/retry/cases.json); once, after this wait, or after a refusal's `Retry-After` when that is longer. A request whose credential was refused is renewed and sent again at once, without this wait, and one unanswered at its deadline (`httpRequestTimeoutMs`) is not made again.\"\n    },\n    {\n      \"name\": \"streamOpenTimeoutMs\",\n      \"value\": 30000,\n      \"docs\": \"How long a client waits for the gateway to answer the request that opens its stream (POST /bus/subscribe): for the answer's status and headers. Unanswered here, the open has failed, and the stream is opened again on the backoff (`reconnectMs`), as after any open that failed. Without it, a gateway that accepts the connection and says nothing is waited on for as long as the process lives, and the stream is never opened again. The gateway answers an open as promptly as one of its own operations, so this is as long as `httpRequestTimeoutMs`. Only the answer is bounded here. An answer that refuses the open has its body read within `httpRequestTimeoutMs`, as any refusal's is: one not read by then is the refusal with none of the gateway's words. An open stream that carries nothing for a while has not failed, since a knowledge base where nothing happens has nothing to send.\"\n    },\n    {\n      \"name\": \"reconnectMs\",\n      \"value\": 5000,\n      \"docs\": \"The first wait before a failed stream is opened again. Each further failure doubles it, up to `maxReconnectMs`, and a successful open resets it. Also the cadence at which a transport with no usable credential checks for one, which costs no request.\"\n    },\n    {\n      \"name\": \"maxReconnectMs\",\n      \"value\": 60000,\n      \"docs\": \"The ceiling of the reconnect backoff: a long outage settles at about one attempt a minute instead of growing without bound.\"\n    },\n    {\n      \"name\": \"degradedThresholdMs\",\n      \"value\": 3000,\n      \"docs\": \"How long a stream may be reconnecting before its state becomes degraded.\"\n    },\n    {\n      \"name\": \"lingerMs\",\n      \"value\": 1000,\n      \"docs\": \"How long a superseded connection keeps draining after a make-before-break handoff. Closing it the instant its replacement opens discards replies already written to the old socket and not yet read. The overlap doubles nothing: a frame both connections carry has one id, and is delivered once (`seenEventIdsCount`).\"\n    },\n    {\n      \"name\": \"seenEventIdsCount\",\n      \"value\": 512,\n      \"docs\": \"How many of the event ids it delivered last a client remembers. A frame whose id is among them is one it has delivered already, and is dropped: that is what makes a frame carried by both streams of a handoff, or replayed to the new one, arrive once. A client that remembers fewer delivers twice whenever more than that many events pass between the two copies.\"\n    },\n    {\n      \"name\": \"reconnectDebounceMs\",\n      \"value\": 100,\n      \"docs\": \"How long additions to the subscription are gathered before the stream is reopened with them. Short, because a new scope needs to be live now.\"\n    },\n    {\n      \"name\": \"lazyRemoveMs\",\n      \"value\": 5000,\n      \"docs\": \"How long a removal from the subscription waits before the stream is reopened without it. Removal only narrows delivery, and reopening on every scope a viewer brushes past would churn the connection.\"\n    },\n    {\n      \"name\": \"refreshRetry\",\n      \"value\": {\n        \"attempts\": 4,\n        \"initialDelayMs\": 500,\n        \"maxDelayMs\": 4000\n      },\n      \"docs\": \"The retry budget of one token renewal: long enough to ride out a gateway restart or a rolling deploy, short enough that a user with no connectivity is told within seconds rather than a minute.\"\n    },\n    {\n      \"name\": \"refreshBeforeExpMs\",\n      \"value\": 300000,\n      \"docs\": \"The LARGEST margin before expiry at which a token is proactively renewed. A ceiling, not the margin: the margin is half the token's own lifetime, capped here. A fixed margin can equal the lifetime an issuer mints (Keycloak's default is five minutes), which makes every renewal already due: an idle signed-in page then sends over a hundred token requests a second.\"\n    },\n    {\n      \"name\": \"minRefreshDelayMs\",\n      \"value\": 10000,\n      \"docs\": \"The shortest the proactive renewal ever waits. A timer due now that reschedules itself on arrival is a closed loop; a floor makes that impossible, so even an issuer minting expired tokens gets one attempt per interval. Waiting is cheap here: a 401 still drives a renewal.\"\n    },\n    {\n      \"name\": \"devicePollMs\",\n      \"value\": 5000,\n      \"docs\": \"How long a sign-in by the device grant (RFC 8628) waits before each time it asks the token endpoint whether the person has approved the code, when the issuer's answer states no `interval`. RFC 8628 \u00A73.2 names five seconds: an issuer that wants a client to ask less often says so.\"\n    },\n    {\n      \"name\": \"deviceSlowDownMs\",\n      \"value\": 5000,\n      \"docs\": \"How much longer a sign-in by the device grant waits between its asks, for that ask and every one after it, each time the issuer answers `slow_down`. RFC 8628 \u00A73.5 names five seconds, so an issuer that says it again is given more time again.\"\n    },\n    {\n      \"name\": \"devicePollFloorMs\",\n      \"value\": 1000,\n      \"docs\": \"The shortest a sign-in by the device grant ever waits between its asks of the token endpoint, whatever `interval` the issuer states. An issuer that states zero, or a fraction of a second, would otherwise be asked again at once for as long as the code lives; a floor makes that impossible, as `minRefreshDelayMs` does for renewals. RFC 8628 sets no lower bound, and a second is not long enough for a person who has approved the code to notice.\"\n    },\n    {\n      \"name\": \"invalidationWindowMs\",\n      \"value\": 1000,\n      \"docs\": \"How long bus-driven invalidations of one cache key fold together (CACHE-SEMANTICS B19). The first runs at once; any more inside the window become one refetch at its end. Each refetch is a request the session's principal pays for, and another principal's bulk write invalidates an observed key once per event.\"\n    },\n    {\n      \"name\": \"saveDebounceMs\",\n      \"value\": 50,\n      \"docs\": \"How long a cache that keeps its values waits, after they last changed, before it saves them (CACHE-SEMANTICS B17): a burst of changes is one save. Disposing the cache makes a save it owes at once.\"\n    },\n    {\n      \"name\": \"maxStoredBytesCount\",\n      \"value\": 2097152,\n      \"docs\": \"The largest document, in bytes, a cache keeps of its values (CACHE-SEMANTICS B17). One larger loses the entries that have gone longest without a new value until it fits: what an origin may keep is a few megabytes, and the cache shares it with everything else the origin keeps.\"\n    },\n    {\n      \"name\": \"errorsKeptForFirstReaderCount\",\n      \"value\": 100,\n      \"docs\": \"How many of what a stream says it keeps for its first reader while none has come: a session's errors, its own and its transport's failures, a transport's failures, a registry's own errors, and a worker's claim refusals and stalls. One more drops the oldest kept, so the first reader hears the latest this many, in the order they were said. A registry reads a session as soon as it is handed back, so it hears everything the opening said, which is a handful; the bound is for a stream nobody reads, which would otherwise keep everything it says until it ends.\"\n    },\n    {\n      \"name\": \"jobSilenceMs\",\n      \"value\": 10000,\n      \"docs\": \"How long a job a client is following may say nothing before the client asks for its status. A job's progress and its end reach the client as passing frames, which a dropped stream loses and nothing redelivers; `job:status-requested` is how a follower learns what it missed. Every frame of the job starts the wait again.\"\n    },\n    {\n      \"name\": \"jobStatusPollMs\",\n      \"value\": 5000,\n      \"docs\": \"How often a client asks for the status of a job that has been silent for `jobSilenceMs`, until the job says something or its status is an end.\"\n    },\n    {\n      \"name\": \"jobPollMs\",\n      \"value\": 1000,\n      \"docs\": \"How often a job's `pollUntilComplete` asks for its status (`job:status-requested`) until the status is an end, when its caller names no interval of its own.\"\n    },\n    {\n      \"name\": \"jobPollTimeoutMs\",\n      \"value\": 60000,\n      \"docs\": \"How long a job's `pollUntilComplete` goes on asking for its status before it fails as timed out, when its caller names no limit of its own: from its first ask, its asks and the waits between them included.\"\n    },\n    {\n      \"name\": \"generationStallFloorMs\",\n      \"value\": 120000,\n      \"docs\": \"The shortest a client waits, with a generation it follows saying nothing, before it asks for the job to be cancelled and gives up on it. A floor, so a job that never says anything at all is caught whatever its size.\"\n    },\n    {\n      \"name\": \"generationStallPerTokenMs\",\n      \"value\": 75,\n      \"docs\": \"How long a followed generation may be silent for each token it was asked for. A generation says nothing while its model writes, so the wait grows with the length of what was asked: four thousand tokens allow five minutes. The floor applies below it.\"\n    },\n    {\n      \"name\": \"generationStallAssumedTokensCount\",\n      \"value\": 500,\n      \"docs\": \"The length assumed of a generation whose request states no `maxTokens`: the worker's own ceiling for one. At this length the floor decides the wait.\"\n    },\n    {\n      \"name\": \"delegateSilenceMs\",\n      \"value\": 180000,\n      \"docs\": \"How long a delegated job a client's state is following may say nothing before that state says the job has gone quiet (`mark:delegate-timeout`). Not a deadline on the job: the job goes on, the state keeps following it, and a completion that arrives later still ends it. Above the worker's heartbeat, so reaching it means silence and not a long call.\"\n    },\n    {\n      \"name\": \"jobClaimTimeoutMs\",\n      \"value\": 10000,\n      \"docs\": \"How long a party that takes jobs waits for the answer to one claim (`job:claim`), from the call and its emit included, as `busRequestTimeoutMs` is for any request. A claim is answered at once, with a job or with nothing pending; one still unanswered here is given up and reported as a refusal, and the party asks again at its next idle moment.\"\n    },\n    {\n      \"name\": \"heldJobStallMs\",\n      \"value\": 900000,\n      \"docs\": \"How long a held job may show no activity (its claim, a progress report, its settle) before whoever holds it calls it stalled. Not a limit on how long a job runs: one that keeps reporting is never stalled. The dispatcher's own sweep of running jobs is the backstop for a holder too wedged to notice.\"\n    },\n    {\n      \"name\": \"heldJobStallCheckMs\",\n      \"value\": 60000,\n      \"docs\": \"How often a party that holds a job looks at how long it has shown no activity.\"\n    },\n    {\n      \"name\": \"markCommitTimeoutMs\",\n      \"value\": 60000,\n      \"docs\": \"How long a worker waits for the record to acknowledge a commit of annotations (`mark:commit`), and then, when no acknowledgement came, for the answer to its question whether the batch's last annotation is on the resource (`browse:annotation-requested`). Each wait is from its request's call, its emit included, as `busRequestTimeoutMs` is for any request. Generous beside an append, since a batch is a unit's annotations and the record may be catching up, and finite, since a wait on an acknowledgement that never comes would hold the job forever.\"\n    },\n    {\n      \"name\": \"generatedTextAsksCount\",\n      \"value\": 8,\n      \"docs\": \"How many times a worker asks for the anchored text of a PDF it has just yielded (`GET /resources/{id}/anchored-text`) before it gives up on anchoring that PDF's citations. The text is the Smelter's to derive and is not there the moment the resource is. Each ask is answered at once when the text is stored, and otherwise waits at the Archivist for the Smelter to say it has settled the content (`smelt:settled`) before it is answered that the text is not there yet. So the count bounds the whole wait, and a worker that reaches it completes the job with the resource and without the citations.\"\n    },\n    {\n      \"name\": \"anchoredTextReaskMs\",\n      \"value\": 5000,\n      \"docs\": \"How long a viewer waits before it asks again for a resource's anchored text (`GET /resources/{id}/anchored-text`), after an answer that the text is not there yet or an ask that got no answer. The Archivist holds an ask while the Smelter reads the content and answers as soon as it has, so this wait is only for the answers that come at once: a text that is not there and is not being read, and a failure. A viewer does not annotate a resource until it holds the resource's text.\"\n    },\n    {\n      \"name\": \"hoverDelayMs\",\n      \"value\": 150,\n      \"docs\": \"How long a pointer rests on an annotation before the viewer says it is hovered. Shorter, and a pointer crossing the page hovers everything on its way.\"\n    },\n    {\n      \"name\": \"searchDebounceMs\",\n      \"value\": 250,\n      \"docs\": \"How long a search waits after its query last changed before it asks. A query still being typed is not asked for letter by letter.\"\n    },\n    {\n      \"name\": \"discoveryIntervalMs\",\n      \"value\": 5000,\n      \"docs\": \"How often a launcher's discovery document is read again, unless a caller says otherwise. A launcher rewrites it on every change to its stack, so a list of the knowledge bases it manages is a few seconds behind at worst, and the document is not read without pause.\"\n    },\n    {\n      \"name\": \"checksAtOnceCount\",\n      \"value\": 4,\n      \"docs\": \"How many of the resources open in a knowledge base a registry checks against it at once when its session comes up. A connection that has just opened is not handed every check together.\"\n    }\n  ]\n}\n";
    internal const string Errors = "{\n  \"$comment\": \"AUTHORITY for the error codes a Xynolog client reports. Every SDK generates its code types and its classifiers from this file, so a code means one thing in every language. TypeScript: the consumer-owned generator writes sdk/typescript/core/src/error-codes.ts. A code belongs here only when something produces it: a member nothing emits promises a distinction the system does not make.\",\n  \"busRequest\": {\n    \"docs\": \"Why a bus request did not resolve. Some members restate a failure the answering peer declared on the wire (`wire` names its `CommandError.code`); the rest are facts only the requesting side knows, which is why this vocabulary and the wire's stay separate.\",\n    \"unrecognizedFailure\": \"bus.rejected\",\n    \"codes\": [\n      {\n        \"code\": \"bus.timeout\",\n        \"docs\": \"No reply arrived within the time the request allowed.\"\n      },\n      {\n        \"code\": \"bus.rejected\",\n        \"docs\": \"The peer answered with a failure that states no code, or one CommandError does not list, which is read as none.\"\n      },\n      {\n        \"code\": \"bus.closed\",\n        \"docs\": \"The bus stopped before a reply came: its client was disposed, or its transport closed.\"\n      },\n      {\n        \"code\": \"bus.not-found\",\n        \"wire\": \"not-found\",\n        \"docs\": \"The peer says this resource does not exist in its knowledge base.\"\n      },\n      {\n        \"code\": \"bus.unsubscribed\",\n        \"docs\": \"THIS transport is not subscribed to the reply channel: a local misconfiguration, caught before emitting. Not to be confused with `bus.peer-unavailable`, which is the opposite end.\"\n      },\n      {\n        \"code\": \"bus.peer-unavailable\",\n        \"wire\": \"peer-unavailable\",\n        \"docs\": \"The service that answers this channel is not connected. Transient by nature, a peer still starting, and therefore the one failure on this list worth retrying.\"\n      },\n      {\n        \"code\": \"bus.unauthorized\",\n        \"wire\": \"unauthorized\",\n        \"docs\": \"The peer says this caller may not do what it asked: authenticated, not permitted. Retrying under the same credential cannot succeed, so a consumer surfaces it and never spins on it.\"\n      },\n      {\n        \"code\": \"bus.none-pending\",\n        \"wire\": \"none-pending\",\n        \"docs\": \"The peer declined and nothing went wrong: a `job:claim` found no pending job of the requested types. The one member a consumer parks on.\"\n      }\n    ]\n  },\n  \"transport\": {\n    \"docs\": \"Transport-neutral failure vocabulary. Every transport maps its native failures to one of these, so a routing layer matches on the code without knowing the wire kind. Over HTTP the mapping is by status: `status` is an exact status, `statusFrom` every status at or above it.\",\n    \"unclassified\": \"error\",\n    \"codes\": [\n      {\n        \"code\": \"unauthorized\",\n        \"status\": 401,\n        \"docs\": \"Authentication is required: the token is missing, expired, or refused. A 429 whose `code` is `refusal-rate` refuses the token too, and is reported as this code with its own status.\"\n      },\n      {\n        \"code\": \"forbidden\",\n        \"status\": 403,\n        \"docs\": \"Authenticated, and lacking permission.\"\n      },\n      {\n        \"code\": \"not-found\",\n        \"status\": 404,\n        \"docs\": \"The resource is missing.\"\n      },\n      {\n        \"code\": \"conflict\",\n        \"status\": 409,\n        \"docs\": \"A concurrent modification, a duplicate, or another conflict with current state.\"\n      },\n      {\n        \"code\": \"bad-request\",\n        \"status\": 400,\n        \"docs\": \"The request is malformed.\"\n      },\n      {\n        \"code\": \"unprocessable\",\n        \"status\": 422,\n        \"docs\": \"The request is well formed and cannot be carried out as it stands: an `Idempotency-Key` used for two different requests. Sent again, it is refused again.\"\n      },\n      {\n        \"code\": \"rate-limited\",\n        \"status\": 429,\n        \"docs\": \"A limit refused it; the refusal's `Retry-After` says when to return.\"\n      },\n      {\n        \"code\": \"unavailable\",\n        \"statusFrom\": 500,\n        \"docs\": \"The gateway is unreachable, the network failed, or the server answered 5xx.\"\n      },\n      {\n        \"code\": \"error\",\n        \"docs\": \"A failure no other member names.\"\n      }\n    ]\n  },\n  \"job\": {\n    \"docs\": \"Why a job its client follows ended without a result. A failure the queue will retry is not one of these: the job goes on, and its follower is told of the setback and keeps following.\",\n    \"codes\": [\n      {\n        \"code\": \"job.failed\",\n        \"docs\": \"The job failed and will not be tried again: the failure its worker reported, or the one its status states.\"\n      },\n      {\n        \"code\": \"job.cancelled\",\n        \"docs\": \"The job was cancelled before it ended, as its status states. Nothing announces a cancellation: its follower learns of it when it asks for the job's status.\"\n      },\n      {\n        \"code\": \"job.stalled\",\n        \"docs\": \"The job said nothing for longer than its follower allows. The follower has asked for that job to be cancelled.\"\n      }\n    ]\n  },\n  \"session\": {\n    \"docs\": \"Why a session itself is unusable, or what its client keeps could not be kept or written. Per-request failures stay with their caller.\",\n    \"codes\": [\n      {\n        \"code\": \"session.construct-failed\",\n        \"docs\": \"A session for the knowledge base could not be built or made ready.\"\n      },\n      {\n        \"code\": \"session.auth-failed\",\n        \"docs\": \"The stored credential could not be validated at startup, for a reason other than the gateway refusing it.\"\n      },\n      {\n        \"code\": \"session.refresh-exhausted\",\n        \"docs\": \"The session could not be renewed: the issuer refused, or stayed unreachable until the retry budget was spent. Not a prompt to retry: retrying already happened.\"\n      },\n      {\n        \"code\": \"session.credential-refused\",\n        \"docs\": \"The gateway refused a token the issuer had just issued. The two disagree about who may sign in, and renewing again cannot change the answer: the session is over, and signing in again is what is left.\"\n      },\n      {\n        \"code\": \"session.keep-failed\",\n        \"docs\": \"The sign-in the session holds could not be read before its client saved what it keeps, or could not record the person the gateway named, so it is not known to name the person that is kept for: the client keeps nothing more for the rest of its life. The session itself goes on, and says so once on its errors stream.\"\n      },\n      {\n        \"code\": \"session.save-refused\",\n        \"docs\": \"The storage refused a write of what the session's client keeps. The save stays owed: the client's next change, or its closing, writes it again, and what its closing cannot write is lost. The session says so on its errors stream once for each write the storage refuses, with what the storage said, a refusal of its closing among them, before the stream ends. The session itself goes on.\"\n      }\n    ]\n  },\n  \"signIn\": {\n    \"docs\": \"Why a person could not be signed in at the issuer a knowledge base trusts, or a session could not be renewed there. Over the authorization-code grant, the device grant, the refresh grant and revocation alike.\",\n    \"codes\": [\n      { \"code\": \"no-issuer\", \"docs\": \"The knowledge base trusts no external issuer: there is nowhere to sign in.\" },\n      { \"code\": \"discovery\", \"docs\": \"The knowledge base did not say which issuer it trusts, or the issuer did not describe itself, or described another issuer, or offers no endpoint the grant needs.\" },\n      { \"code\": \"no-pending\", \"docs\": \"A sign-in response arrived and no sign-in is pending here: it was completed already, or begun somewhere else.\" },\n      { \"code\": \"state\", \"docs\": \"The sign-in response does not belong to the pending sign-in.\" },\n      { \"code\": \"denied\", \"docs\": \"The person, or the issuer, refused the sign-in.\" },\n      { \"code\": \"expired\", \"docs\": \"The device code ran out before it was approved.\" },\n      { \"code\": \"aborted\", \"docs\": \"The sign-in was abandoned by whoever began it.\" },\n      { \"code\": \"exchange\", \"docs\": \"The issuer refused a token request, a device authorization or a revocation, or answered without what was asked for.\" }\n    ]\n  },\n  \"kbIdentity\": {\n    \"docs\": \"Why a knowledge base that was reached with a fresh sign-in could not be registered: it has to say who it is, and nothing stands in for its answer.\",\n    \"codes\": [\n      { \"code\": \"unreachable\", \"docs\": \"The knowledge base was not reached, so it said nothing.\" },\n      { \"code\": \"not-reported\", \"docs\": \"The knowledge base answered that it cannot say what it is.\" }\n    ]\n  },\n  \"spanRefusal\": {\n    \"docs\": \"Why no annotation was built of a span: the span is not the text's, or, for a PDF, is nowhere on its pages, or the PDF's anchored text does not hold together. specs/src/annotations/builder-cases.json holds when each is given.\",\n    \"codes\": [\n      { \"code\": \"span-out-of-range\", \"docs\": \"The span's offsets are not two whole numbers from 0, the second no less than the first, within the text.\" },\n      { \"code\": \"exact-mismatch\", \"docs\": \"The words the span states are not the text between its offsets.\" },\n      { \"code\": \"prefix-mismatch\", \"docs\": \"The prefix the span states is not the text just before it.\" },\n      { \"code\": \"suffix-mismatch\", \"docs\": \"The suffix the span states is not the text just after it.\" },\n      { \"code\": \"nothing-located\", \"docs\": \"No item of the PDF's anchored text holds any of the span, so it is nowhere on a page.\" },\n      { \"code\": \"exact-not-covered\", \"docs\": \"The items of the PDF's anchored text that hold the span do not have its words.\" },\n      { \"code\": \"item-out-of-range\", \"docs\": \"An item of the PDF's anchored text is no stretch of that text: its offsets are not two whole numbers from 0, the second no less than the first, within the text. This one is said of the anchored text and not of the span: the items are what say where the text is on a page, and no span is built on an anchored text one of whose items cannot be.\" }\n    ]\n  },\n  \"control\": {\n    \"docs\": \"Why a request of the launcher's control API (`xynolog control`, contract/LAUNCHER-CONTROL.md) failed. The launcher sends one in each error's data, and Desktop reads it. A knowledge base never sends one.\",\n    \"codes\": [\n      { \"code\": \"control.invalid-params\", \"docs\": \"The request's params are not what its method's schema admits. The error's fields name each fault; JSON-RPC's own invalid-params code (-32602) carries it.\" },\n      { \"code\": \"control.unsupported-api-version\", \"docs\": \"The request is written to a version of the control API this launcher does not speak. The error's supported field names the ones it does.\" },\n      { \"code\": \"control.invalid-request\", \"docs\": \"The launcher refuses the request as the command line refuses the same options: they contradict each other, or do not apply to what they name.\" },\n      { \"code\": \"control.invalid-service\", \"docs\": \"The request names a service or a group the launcher has none of.\" },\n      { \"code\": \"control.invalid-value\", \"docs\": \"The launcher refuses a setting's value, as a start would refuse it. The previous value is kept.\" },\n      { \"code\": \"control.unknown-setting\", \"docs\": \"The request names a setting the launcher does not keep.\" },\n      { \"code\": \"control.target-required\", \"docs\": \"Several stacks could be meant and the request names none of them. The error's choices name each; nothing was done.\" },\n      { \"code\": \"control.target-ambiguous\", \"docs\": \"The root the request names is the basename of several registered roots. The error's choices name each by its path; nothing was done.\" },\n      { \"code\": \"control.root-not-found\", \"docs\": \"The root the request names is not a knowledge base's clone: no such directory, no .xynolog/ in it, or a project file the launcher refuses.\" },\n      { \"code\": \"control.root-not-registered\", \"docs\": \"The root the request names is not in the registry.\" },\n      { \"code\": \"control.stack-not-running\", \"docs\": \"The request needs a stack of its target recorded on this machine, and none is.\" },\n      { \"code\": \"control.stack-running\", \"docs\": \"The request would change what a recorded stack depends on: stop the stack first.\" },\n      { \"code\": \"control.start-in-progress\", \"docs\": \"Another xynolog start of the same knowledge base holds its start lock.\" },\n      { \"code\": \"control.runtime-unavailable\", \"docs\": \"No container runtime the request can use is on the launcher's PATH.\" },\n      { \"code\": \"control.dependency-unavailable\", \"docs\": \"A program the request needs besides a container runtime (gh, for a codespace) is not on the launcher's PATH.\" },\n      { \"code\": \"control.unreachable\", \"docs\": \"What the request needs to reach did not answer: the knowledge base, its issuer, or a codespace's forward.\" },\n      { \"code\": \"control.confirmation-required\", \"docs\": \"The request would destroy something, and does not state that a person confirmed it.\" },\n      { \"code\": \"control.unreadable-state\", \"docs\": \"The launcher's own record of this machine (the stack record, the registry, the sign-in store) cannot be read. Nothing was assumed in its place.\" },\n      { \"code\": \"control.already-signed-in\", \"docs\": \"The launcher's stored session for the target is valid: there is nothing to sign in to.\" },\n      { \"code\": \"control.sign-in-failed\", \"docs\": \"The person was not signed in: the issuer refused or the code expired, the gateway refused the token, or the session could not be kept. Nothing was stored.\" },\n      { \"code\": \"control.cancelled\", \"docs\": \"The client cancelled the request before it ended.\" },\n      { \"code\": \"control.failed\", \"docs\": \"The request failed for a reason no other code names. Its message says why, as the command line would.\" }\n    ]\n  }\n}\n";
    internal const string Retry = "{\n  \"$comment\": \"Whether a failed request is worth another attempt, as every implementation must answer it. `rules`: the four named rules, each for one context, asked about a response's `status`, the request's `method`, and whether it carries an `Idempotency-Key` (`keyed`); a row that omits `status` or `method` leaves it unstated, and one that omits `keyed` states a request with no key. `boot`: a boot pass or a bus request, where the peer is usually seconds from ready. `job`: a job's retry budget, where not retrying discards paid work. `transport`: an HTTP client's request, retried only when a repeat cannot cause a second effect: its method cannot, or it carries an `Idempotency-Key`, whose repeat the server answers as it answered the first. A 401 is not retried by any rule: a refused credential is renewed before any rule is asked (contract/TRANSPORT-CONTRACT.md \u00A7 A refused credential), and the same token gets the same answer. `refresh`: exchanging a refresh token at its issuer, where the issuer's answer is the verdict and its absence never is. `retryAfter`: the wait a `Retry-After` header states, in milliseconds, when it gives whole seconds, the form the gateway sends; `ms` is null when it states none. Every SDK runs `retryAfter` and every rule it keeps, and names each rule it does not keep and why. `job` is the worker's: an SDK may leave it out, and every worker runs it.\",\n  \"runBy\": {\n    \"ocaml\": [\"sdk/ocaml/sdk/test/completion_behavior.ml\"],\n    \"haskell\": [\"sdk/haskell/sdk/test/Main.hs\"],\n    \"csharp\": [\"sdk/csharp/sdk/tests/Xynolog.Tests/RetryTests.cs\"],\n    \"typescript\": [\"sdk/typescript/core/src/__tests__/retry-agreement.test.ts\"],\n    \"rust\": [\"sdk/rust/sdk/src/retry.rs\", \"sdk/rust/sdk/tests/retry_cases.rs\"],\n    \"python\": [\"sdk/python/sdk/tests/test_retry.py\"],\n    \"go\": [\"sdk/go/retry_test.go\"],\n    \"worker\": [\"worker/tests/test_retry_job_rule.py\"],\n    \"swift\": [\"sdk/swift/sdk/Tests/XynologTests/TransportTablesTests.swift\"],\n    \"kotlin\": [\"sdk/kotlin/sdk/src/test/kotlin/xynolog/retry/RetryCasesTest.kt\"]\n  },\n  \"rules\": [\n    {\n      \"why\": \"429 is the server saying not now\",\n      \"rule\": \"boot\",\n      \"status\": 429,\n      \"retries\": true\n    },\n    {\n      \"why\": \"503 is a promise to recover\",\n      \"rule\": \"boot\",\n      \"status\": 503,\n      \"retries\": true\n    },\n    {\n      \"why\": \"504 is a promise to recover\",\n      \"rule\": \"boot\",\n      \"status\": 504,\n      \"retries\": true\n    },\n    {\n      \"why\": \"500 is an unclassified fault: replaying it inside a boot pass re-runs whatever broke it\",\n      \"rule\": \"boot\",\n      \"status\": 500,\n      \"retries\": false\n    },\n    {\n      \"why\": \"401 means the gateway is up and refused\",\n      \"rule\": \"boot\",\n      \"status\": 401,\n      \"retries\": false\n    },\n    {\n      \"why\": \"400 will be refused again\",\n      \"rule\": \"boot\",\n      \"status\": 400,\n      \"retries\": false\n    },\n    {\n      \"why\": \"422 is a key used for another request, and will be refused again\",\n      \"rule\": \"boot\",\n      \"status\": 422,\n      \"retries\": false\n    },\n    {\n      \"why\": \"408 is a timeout\",\n      \"rule\": \"job\",\n      \"status\": 408,\n      \"retries\": true\n    },\n    {\n      \"why\": \"429 is the server saying not now\",\n      \"rule\": \"job\",\n      \"status\": 429,\n      \"retries\": true\n    },\n    {\n      \"why\": \"500 is retried here where boot refuses it: the alternative is discarding paid work\",\n      \"rule\": \"job\",\n      \"status\": 500,\n      \"retries\": true\n    },\n    {\n      \"why\": \"503 is a promise to recover\",\n      \"rule\": \"job\",\n      \"status\": 503,\n      \"retries\": true\n    },\n    {\n      \"why\": \"400 will be refused again\",\n      \"rule\": \"job\",\n      \"status\": 400,\n      \"retries\": false\n    },\n    {\n      \"why\": \"401 will be refused again\",\n      \"rule\": \"job\",\n      \"status\": 401,\n      \"retries\": false\n    },\n    {\n      \"why\": \"404 will be refused again\",\n      \"rule\": \"job\",\n      \"status\": 404,\n      \"retries\": false\n    },\n    {\n      \"why\": \"a 401 on a POST is not retried: a refused credential is renewed, never retried\",\n      \"rule\": \"transport\",\n      \"status\": 401,\n      \"method\": \"POST\",\n      \"retries\": false\n    },\n    {\n      \"why\": \"a 401 on a GET is not retried either: the method makes no difference to a refused credential\",\n      \"rule\": \"transport\",\n      \"status\": 401,\n      \"method\": \"GET\",\n      \"retries\": false\n    },\n    {\n      \"why\": \"a 401 with no method stated is not retried\",\n      \"rule\": \"transport\",\n      \"status\": 401,\n      \"retries\": false\n    },\n    {\n      \"why\": \"a 502 on a POST is not retried: it may already have been processed, and a repeat writes twice\",\n      \"rule\": \"transport\",\n      \"status\": 502,\n      \"method\": \"POST\",\n      \"retries\": false\n    },\n    {\n      \"why\": \"a 502 on a POST that carries an Idempotency-Key is retried: whatever the first did, the repeat is answered as it was\",\n      \"rule\": \"transport\",\n      \"status\": 502,\n      \"method\": \"POST\",\n      \"keyed\": true,\n      \"retries\": true\n    },\n    {\n      \"why\": \"a 503 on a keyed POST is retried\",\n      \"rule\": \"transport\",\n      \"status\": 503,\n      \"method\": \"POST\",\n      \"keyed\": true,\n      \"retries\": true\n    },\n    {\n      \"why\": \"a 400 on a keyed POST will be refused again: a key makes a repeat harmless, not a refused request acceptable\",\n      \"rule\": \"transport\",\n      \"status\": 400,\n      \"method\": \"POST\",\n      \"keyed\": true,\n      \"retries\": false\n    },\n    {\n      \"why\": \"a 422 on a keyed POST is a key used for another request, and is refused again\",\n      \"rule\": \"transport\",\n      \"status\": 422,\n      \"method\": \"POST\",\n      \"keyed\": true,\n      \"retries\": false\n    },\n    {\n      \"why\": \"a keyed request is retried with no method stated: the key, not the method, is what makes the repeat harmless\",\n      \"rule\": \"transport\",\n      \"status\": 503,\n      \"keyed\": true,\n      \"retries\": true\n    },\n    {\n      \"why\": \"a 502 on a GET is retried\",\n      \"rule\": \"transport\",\n      \"status\": 502,\n      \"method\": \"GET\",\n      \"retries\": true\n    },\n    {\n      \"why\": \"a 503 on a PUT is retried: PUT is idempotent\",\n      \"rule\": \"transport\",\n      \"status\": 503,\n      \"method\": \"PUT\",\n      \"retries\": true\n    },\n    {\n      \"why\": \"a 500 on a DELETE is retried: DELETE is idempotent\",\n      \"rule\": \"transport\",\n      \"status\": 500,\n      \"method\": \"DELETE\",\n      \"retries\": true\n    },\n    {\n      \"why\": \"a 429 on a POST is not retried by this rule\",\n      \"rule\": \"transport\",\n      \"status\": 429,\n      \"method\": \"POST\",\n      \"retries\": false\n    },\n    {\n      \"why\": \"a 429 on a GET is retried\",\n      \"rule\": \"transport\",\n      \"status\": 429,\n      \"method\": \"GET\",\n      \"retries\": true\n    },\n    {\n      \"why\": \"a 413 on a GET is retried\",\n      \"rule\": \"transport\",\n      \"status\": 413,\n      \"method\": \"GET\",\n      \"retries\": true\n    },\n    {\n      \"why\": \"the method is read in any case\",\n      \"rule\": \"transport\",\n      \"status\": 408,\n      \"method\": \"get\",\n      \"retries\": true\n    },\n    {\n      \"why\": \"a 404 on a GET will be refused again\",\n      \"rule\": \"transport\",\n      \"status\": 404,\n      \"method\": \"GET\",\n      \"retries\": false\n    },\n    {\n      \"why\": \"a 500 with no method stated is not retried: unstated reads as unsafe\",\n      \"rule\": \"transport\",\n      \"status\": 500,\n      \"retries\": false\n    },\n    {\n      \"why\": \"no status is not retried by this rule\",\n      \"rule\": \"transport\",\n      \"method\": \"GET\",\n      \"retries\": false\n    },\n    {\n      \"why\": \"no response at all is the network, not the issuer: the session survives a lost packet\",\n      \"rule\": \"refresh\",\n      \"retries\": true\n    },\n    {\n      \"why\": \"400 is the issuer refusing the grant: terminal on the first answer\",\n      \"rule\": \"refresh\",\n      \"status\": 400,\n      \"retries\": false\n    },\n    {\n      \"why\": \"401 is the issuer refusing the client\",\n      \"rule\": \"refresh\",\n      \"status\": 401,\n      \"retries\": false\n    },\n    {\n      \"why\": \"404 on the token endpoint is a misconfiguration, not a promise to recover: unclassified is terminal\",\n      \"rule\": \"refresh\",\n      \"status\": 404,\n      \"retries\": false\n    },\n    {\n      \"why\": \"408 is not now\",\n      \"rule\": \"refresh\",\n      \"status\": 408,\n      \"retries\": true\n    },\n    {\n      \"why\": \"429 is not now\",\n      \"rule\": \"refresh\",\n      \"status\": 429,\n      \"retries\": true\n    },\n    {\n      \"why\": \"500 is retried here where boot refuses it: one idempotent exchange has no side effect to replay\",\n      \"rule\": \"refresh\",\n      \"status\": 500,\n      \"retries\": true\n    },\n    {\n      \"why\": \"503 is not now\",\n      \"rule\": \"refresh\",\n      \"status\": 503,\n      \"retries\": true\n    }\n  ],\n  \"retryAfter\": [\n    {\n      \"why\": \"whole seconds\",\n      \"header\": \"5\",\n      \"ms\": 5000\n    },\n    {\n      \"why\": \"zero seconds is a stated wait of none\",\n      \"header\": \"0\",\n      \"ms\": 0\n    },\n    {\n      \"why\": \"surrounding whitespace is not part of the value\",\n      \"header\": \" 7 \",\n      \"ms\": 7000\n    },\n    {\n      \"why\": \"no header states no wait\",\n      \"header\": null,\n      \"ms\": null\n    },\n    {\n      \"why\": \"an empty header states no wait\",\n      \"header\": \"\",\n      \"ms\": null\n    },\n    {\n      \"why\": \"the HTTP-date form is not the form the gateway sends\",\n      \"header\": \"Wed, 21 Oct 2026 07:28:00 GMT\",\n      \"ms\": null\n    },\n    {\n      \"why\": \"a fraction is not whole seconds\",\n      \"header\": \"1.5\",\n      \"ms\": null\n    },\n    {\n      \"why\": \"a negative number is not a wait\",\n      \"header\": \"-1\",\n      \"ms\": null\n    }\n  ]\n}\n";
    internal const string Telemetry = "{\n  \"$comment\": \"The telemetry a Xynolog SDK's transports export over OTLP, in any language, when the process they run in exports at all: every span and metric, the transport it comes from, its kind, and the attributes it carries. `transport` is `bus` (the stream and emits) or `content` (uploads and reads). The SDK conformance suite holds each SDK to this table from outside: every row must arrive from its driver, of the listed kind, with every attribute not marked `only`, and whatever arrives under a row's name must carry only that row's attributes. A service that reaches the bus through an SDK exports the rows of the transports it uses; specs/src/service-telemetry/telemetry.json names such services under `sdk`, each with the transports it uses or, of a transport it uses part of, the rows it exports, and their suites hold them to both tables. `xynolog.bus.sent` counts the emits a client sent; the emits a gateway accepted are `xynolog.bus.emit`, a row of that table, so that neither is counted as the other and the difference between them shows. In a span name, `{channel}` is the bus channel. Span kinds are OTLP's; a metric's `instrument` is `counter` (a monotonic sum). The optional thread.id attribute is runtime metadata supplied automatically by some host OpenTelemetry APIs.\",\n  \"spans\": [\n    {\n      \"name\": \"bus.emit:{channel}\",\n      \"transport\": \"bus\",\n      \"kind\": \"producer\",\n      \"meaning\": \"A frame the client sent, in the trace of the work that sent it.\",\n      \"attributes\": [\n        {\n          \"key\": \"bus.channel\"\n        },\n        {\n          \"key\": \"bus.scope\",\n          \"only\": \"on a frame in a resource scope\"\n        },\n        {\n          \"key\": \"thread.id\",\n          \"only\": \"when the host OpenTelemetry API supplies its runtime thread identity\"\n        }\n      ]\n    },\n    {\n      \"name\": \"bus.recv:{channel}\",\n      \"transport\": \"bus\",\n      \"kind\": \"consumer\",\n      \"meaning\": \"A frame the client received, and the work done for it, in the trace the frame was sent under.\",\n      \"attributes\": [\n        {\n          \"key\": \"bus.channel\"\n        },\n        {\n          \"key\": \"bus.scope\",\n          \"only\": \"on a frame in a resource scope\"\n        },\n        {\n          \"key\": \"thread.id\",\n          \"only\": \"when the host OpenTelemetry API supplies its runtime thread identity\"\n        }\n      ]\n    },\n    {\n      \"name\": \"content.put\",\n      \"transport\": \"content\",\n      \"kind\": \"client\",\n      \"meaning\": \"An upload.\",\n      \"attributes\": [\n        {\n          \"key\": \"content.format\"\n        },\n        {\n          \"key\": \"content.size_bytes\"\n        },\n        {\n          \"key\": \"thread.id\",\n          \"only\": \"when the host OpenTelemetry API supplies its runtime thread identity\"\n        }\n      ]\n    },\n    {\n      \"name\": \"content.get\",\n      \"transport\": \"content\",\n      \"kind\": \"client\",\n      \"meaning\": \"A read of a resource's bytes.\",\n      \"attributes\": [\n        {\n          \"key\": \"resource.id\"\n        },\n        {\n          \"key\": \"content.stream\",\n          \"values\": [\n            \"true\"\n          ],\n          \"only\": \"on a read taken as a stream\"\n        },\n        {\n          \"key\": \"thread.id\",\n          \"only\": \"when the host OpenTelemetry API supplies its runtime thread identity\"\n        }\n      ]\n    },\n    {\n      \"name\": \"content.get_graph\",\n      \"transport\": \"content\",\n      \"kind\": \"client\",\n      \"meaning\": \"A read of a resource's description.\",\n      \"attributes\": [\n        {\n          \"key\": \"resource.id\"\n        },\n        {\n          \"key\": \"thread.id\",\n          \"only\": \"when the host OpenTelemetry API supplies its runtime thread identity\"\n        }\n      ]\n    },\n    {\n      \"name\": \"content.get_anchored_text\",\n      \"transport\": \"content\",\n      \"kind\": \"client\",\n      \"meaning\": \"A read of a resource's anchored text.\",\n      \"attributes\": [\n        {\n          \"key\": \"resource.id\"\n        },\n        {\n          \"key\": \"thread.id\",\n          \"only\": \"when the host OpenTelemetry API supplies its runtime thread identity\"\n        }\n      ]\n    }\n,\n    {\n      \"name\": \"content.get_annotations\",\n      \"transport\": \"content\",\n      \"kind\": \"client\",\n      \"meaning\": \"A read of a resource's annotations.\",\n      \"attributes\": [\n        {\n          \"key\": \"resource.id\"\n        },\n        {\n          \"key\": \"thread.id\",\n          \"only\": \"when the host OpenTelemetry API supplies its runtime thread identity\"\n        }\n      ]\n    }\n  ],\n  \"metrics\": [\n    {\n      \"name\": \"xynolog.bus.sent\",\n      \"transport\": \"bus\",\n      \"instrument\": \"counter\",\n      \"meaning\": \"Emits the client sent.\",\n      \"attributes\": [\n        {\n          \"key\": \"bus.channel\"\n        },\n        {\n          \"key\": \"bus.scope\",\n          \"only\": \"on an emit in a resource scope\"\n        }\n      ]\n    }\n  ]\n}\n";
    internal const string Log = "{\n  \"$comment\": \"What a bus log shows of a payload, as every bus log must show it. With XYNOLOG_BUS_LOG set, a Xynolog SDK or service writes one line for each frame it sends or receives, and the last thing on a line is the frame's payload. No line holds a credential. THE RULE reads a name and no channel: the value of a member whose whole name is one of `names`, letter for letter and in the same case, is shown as the text `[withheld]`, wherever in a payload the member is (in the payload itself, in an object within it at any depth, in an object inside an array) and whatever its value is (text, a number, null, an object, an array: the whole value is replaced, and nothing within it is read). THE NAMES are the ones a credential goes by. The registry's payloads declare one credential, the token a resource is cloned by, and name it `token` (`yield:clone-resource-requested` and `yield:clone-create`, which a client sends, and the `response` of `yield:clone-token-generated`, which it receives). But some payloads take any member (an agent's `parameters`, a job's `params` and its `result`, a graph's `metadata`, what a description of a resource or of a representation adds), and a credential put in one is withheld under the name it has elsewhere: `cloneToken`, an upload's name for the token a resource is cloned by; `accessToken` and `refreshToken`, a sign-in's two tokens, and `access_token` and `refresh_token`, as an issuer names them; `apiKey`, an inference provider's key as a knowledge base's configuration names it, and `api_key`, as a Python program does; `clientSecret` and `client_secret`, a service's secret at its issuer, as a program and as the grant that spends it name it; `secret` and `password`; and the header a credential is sent under, which is `authorization` and `Authorization` (two spellings of one header) and, for a provider's key, `x-api-key` and `x-goog-api-key`. A name that only contains one of them is another name, and is shown: a count of a model's tokens (`maxTokens`), a plural (`tokens`), another case (`Token`), the member that names the environment variable a credential is read from (`apiKeyEnv`, `passwordEnv`), an endpoint (`tokenEndpoint`). Everything else is shown as it is: every other member, an array's items in their order, a value that happens to be one of the names. A frame's payload is an object, and so is every case's. A log that can be given a payload that is not one reads an array by the same rule and shows anything else as it is, and holds that in its own tests. A case is a `payload` and what is `shown` of it. How a log writes what it shows (as JSON, as a console's rendering of an object) is its own, so a runner compares values and never text. Every name has a case of its own, and no case withholds under a name that is not listed. A case that is a channel's own payload names the `channel`, and its `payload` is one the registry's schema for that channel admits. Every bus log runs it, in whatever language it is written. A runner that has the registry's payload types holds each case that names a channel to that channel's payload type, the cases to `names`, and `names` to the members the registry's payloads declare. Add a name and its case here before changing an implementation.\",\n  \"runBy\": {\n    \"ocaml\": [\"sdk/ocaml/sdk/test/closure_behavior.ml\"],\n    \"haskell\": [\"sdk/haskell/sdk/test/BusLogCases.hs\"],\n    \"typescript\": [\"sdk/typescript/core/src/__tests__/bus-log-cases.test.ts\"],\n    \"rust\": [\"sdk/rust/sdk/src/bus_log.rs\"],\n    \"python\": [\"sdk/python/sdk/tests/test_bus_log.py\"],\n    \"go\": [\"sdk/go/buslog_test.go\"],\n    \"swift\": [\"sdk/swift/sdk/Tests/XynologTests/TransportTablesTests.swift\"],\n    \"kotlin\": [\"sdk/kotlin/sdk/src/test/kotlin/xynolog/bus/BusLogTest.kt\"],\n    \"csharp\": [\"sdk/csharp/sdk/tests/Xynolog.Tests/BusLogTests.cs\"]\n  },\n  \"names\": [\n    \"token\",\n    \"cloneToken\",\n    \"accessToken\",\n    \"access_token\",\n    \"refreshToken\",\n    \"refresh_token\",\n    \"apiKey\",\n    \"api_key\",\n    \"clientSecret\",\n    \"client_secret\",\n    \"secret\",\n    \"password\",\n    \"authorization\",\n    \"Authorization\",\n    \"x-api-key\",\n    \"x-goog-api-key\"\n  ],\n  \"cases\": [\n    {\n      \"why\": \"yield:clone-resource-requested, as a client sends it: the request is its token\",\n      \"channel\": \"yield:clone-resource-requested\",\n      \"payload\": { \"token\": \"clone-token-of-the-request\" },\n      \"shown\": { \"token\": \"[withheld]\" }\n    },\n    {\n      \"why\": \"yield:clone-create, as the gateway has it: the token is withheld, and what it rides with is shown, the gateway's stamp included\",\n      \"channel\": \"yield:clone-create\",\n      \"payload\": {\n        \"_userId\": \"did:web:example.org:users:alice\",\n        \"token\": \"clone-token-of-the-command\",\n        \"name\": \"A clone\",\n        \"storageUri\": \"file://clones/a-clone.md\",\n        \"contentChecksum\": \"9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08\",\n        \"byteSize\": 4,\n        \"format\": \"text/markdown\"\n      },\n      \"shown\": {\n        \"_userId\": \"did:web:example.org:users:alice\",\n        \"token\": \"[withheld]\",\n        \"name\": \"A clone\",\n        \"storageUri\": \"file://clones/a-clone.md\",\n        \"contentChecksum\": \"9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08\",\n        \"byteSize\": 4,\n        \"format\": \"text/markdown\"\n      }\n    },\n    {\n      \"why\": \"yield:clone-token-generated, as a client receives it: the token is a member of the reply's response\",\n      \"channel\": \"yield:clone-token-generated\",\n      \"payload\": {\n        \"response\": {\n          \"token\": \"clone-token-of-the-reply\",\n          \"expiresAt\": \"2026-10-11T00:00:00.000Z\",\n          \"resource\": { \"@context\": \"https://schema.org/\", \"@id\": \"res-1\", \"name\": \"A resource